CREATE     PROCEDURE [synapse_fo].[usp_Insert_VENDSETTLEMENT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:03
	Description: Insert stored procedure for VENDSETTLEMENT from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[VENDSETTLEMENT]
	(
		[ACCOUNTNUM],
		[CANBEREVERSED],
		[CASHDISCOUNTLEDGERDIMENSION],
		[CLOSEDDATE],
		[CREATEDBY],
		[CREATEDDATETIME],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DUEDATE],
		[EUSALESLIST],
		[EXCHADJUSTMENT],
		[EXCHADJUSTMENTREPORTING],
		--[FileName],
		[FINEAMOUNT_BR],
		[FINECODE_BR],
		[INTERESTAMOUNT_BR],
		[INTERESTCODE_BR],
		[LASTINTERESTDATEDUMMY],
		[LastProcessedChange_DateTime],
		--[LSN],
		[OFFSETACCOUNTNUM],
		[OFFSETCOMPANY],
		[OFFSETRECID],
		[OFFSETTRANSVOUCHER],
		[PARTITION],
		[PENNYDIFF],
		[RECID],
		[RECVERSION],
		[REMITTANCEADDRESS],
		[REPORTINGDATE_RU],
		[REVERSEDRECID_RU],
		[REVERSETRANS_RU],
		[SETTLEAMOUNTCUR],
		[SETTLEAMOUNTMST],
		[SETTLEAMOUNTREPORTING],
		[SETTLEMENTGROUP],
		[SETTLEMENTVOUCHER],
		[SETTLETAX1099AMOUNT],
		[SETTLETAX1099STATEAMOUNT],
		[STATUSVOUCHER],
		--[SysRowId],
		[TAXVOUCHER_RU],
		[THIRDPARTYBANKACCOUNTID],
		[TRANSCOMPANY],
		[TRANSDATE],
		[TRANSOPEN],
		[TRANSRECID],
		[TRANSTYPE],
		[UTILIZEDCASHDISC],
		[VATTAXAGENTAMOUNT_RU],
		[VENDCASHDISCDATE],
		[VENDPAYMENTGROUP]
	)
	SELECT 
		stg.[ACCOUNTNUM],
		stg.[CANBEREVERSED],
		stg.[CASHDISCOUNTLEDGERDIMENSION],
		stg.[CLOSEDDATE],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DUEDATE],
		stg.[EUSALESLIST],
		stg.[EXCHADJUSTMENT],
		stg.[EXCHADJUSTMENTREPORTING],
		--stg.--[FileName],
		stg.[FINEAMOUNT_BR],
		stg.[FINECODE_BR],
		stg.[INTERESTAMOUNT_BR],
		stg.[INTERESTCODE_BR],
		stg.[LASTINTERESTDATEDUMMY],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[OFFSETACCOUNTNUM],
		stg.[OFFSETCOMPANY],
		stg.[OFFSETRECID],
		stg.[OFFSETTRANSVOUCHER],
		stg.[PARTITION],
		stg.[PENNYDIFF],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REMITTANCEADDRESS],
		stg.[REPORTINGDATE_RU],
		stg.[REVERSEDRECID_RU],
		stg.[REVERSETRANS_RU],
		stg.[SETTLEAMOUNTCUR],
		stg.[SETTLEAMOUNTMST],
		stg.[SETTLEAMOUNTREPORTING],
		stg.[SETTLEMENTGROUP],
		stg.[SETTLEMENTVOUCHER],
		stg.[SETTLETAX1099AMOUNT],
		stg.[SETTLETAX1099STATEAMOUNT],
		stg.[STATUSVOUCHER],
		--stg.--[SysRowId],
		stg.[TAXVOUCHER_RU],
		stg.[THIRDPARTYBANKACCOUNTID],
		stg.[TRANSCOMPANY],
		stg.[TRANSDATE],
		stg.[TRANSOPEN],
		stg.[TRANSRECID],
		stg.[TRANSTYPE],
		stg.[UTILIZEDCASHDISC],
		stg.[VATTAXAGENTAMOUNT_RU],
		stg.[VENDCASHDISCDATE],
		stg.[VENDPAYMENTGROUP]	
	FROM [staging_fo].[VENDSETTLEMENT] stg
		LEFT JOIN [synapse_fo].[VENDSETTLEMENT] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
